mapper.select:
SELECT n.id, n.title, n.content, n.notification_type, n.source_type, n.source_id, n.sender_id, n.sender_name, n.recipient_id, n.is_read, n.read_time, n.status, n.create_time, n.update_time, n.deleted, ai.id AS instance_id, ai.status AS instance_status, ai.workflow_id, w.name AS workflow_name, ai.applicant_id, u.real_name AS applicant_name,
CASE WHEN ai.business_type = 'MATERIAL_ENTRY' THEN ma.title WHEN ai.business_type = 'ASSET_DELETION' THEN da.title WHEN ai.business_type = 'ASSET_USAGE' THEN ua.title ELSE NULL END AS business_title FROM sys_notification n LEFT JOIN approval_instance ai ON n.source_id = ai.id LEFT JOIN workflow w ON ai.workflow_id = w.id LEFT JOIN sys_user u ON ai.applicant_id = u.id LEFT JOIN material_application ma ON ai.business_type = 'MATERIAL_ENTRY' AND ai.business_id = ma.id LEFT JOIN asset_deletion_application da ON ai.business_type = 'ASSET_DELETION' AND ai.business_id = da.id LEFT JOIN usage_apply ua ON ai.business_type = 'ASSET_USAGE' AND ai.business_id = ua.id
ORDER BY n.${orderByField} ${orderByDirection}
LIMIT #{offset}, #{limit}

